/** One row of a bulk import, with its assignee and labels already resolved. */
export interface ImportedIssueDraft {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly dueAt: IsoTimestamp | null;
  readonly assigneeId: UserId | null;
  readonly labelNames: readonly string[];
}

export interface IssueImportWrite {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportedIssueDraft[];
}

/**
 * Writes a whole import in one transaction: numbering, missing labels, the
 * issues and the import record. Returns `null` without writing when the key
 * already exists in the workspace, which can only happen if a concurrent
 * import with the same key committed after the caller's replay check.
 */
export async function insertIssueImport(
  input: IssueImportWrite,
): Promise<readonly Issue[] | null> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const taken = tx
      .select({ id: issueImports.id })
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, input.orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (taken) return null;

    const maxNumber = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let nextNumber = (maxNumber?.value ?? 0) + 1;

    const wantedNames = [...new Set(input.rows.flatMap((row) => row.labelNames))];
    const labelIdByName = new Map<string, LabelId>();
    if (wantedNames.length > 0) {
      const existing = tx
        .select({ id: labels.id, name: labels.name })
        .from(labels)
        .where(
          and(
            orgPredicate(labels.orgId, input.orgId),
            inArray(labels.name, wantedNames),
          ),
        )
        .all();
      for (const label of existing) {
        labelIdByName.set(label.name, label.id as LabelId);
      }
    }
    for (const name of wantedNames) {
      if (labelIdByName.has(name)) continue;
      const id = newId() as LabelId;
      tx.insert(labels)
        .values({
          id,
          orgId: input.orgId,
          name,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();
      labelIdByName.set(name, id);
    }

    const created: Issue[] = [];
    const labelRows: { orgId: OrgId; issueId: string; labelId: LabelId }[] = [];

    for (const draft of input.rows) {
      const row = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          number: nextNumber,
          title: draft.title,
          description: draft.description,
          status: draft.status,
          priority: draft.priority,
          authorId: input.authorId,
          assigneeId: draft.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: draft.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();
      nextNumber += 1;

      const labelIds = [
        ...new Set(draft.labelNames.map((name) => labelIdByName.get(name) as LabelId)),
      ];
      for (const labelId of labelIds) {
        labelRows.push({ orgId: input.orgId, issueId: row.id, labelId });
      }
      created.push(toIssue(row, labelIds));
    }

    if (labelRows.length > 0) {
      tx.insert(issueLabels).values(labelRows).run();
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        importedBy: input.authorId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return created;
  });
}

/** The stored result of an earlier import under this key, if the workspace has one. */
export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<{ projectId: ProjectId; issueIds: readonly IssueId[] } | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;

  return {
    projectId: row.projectId as ProjectId,
    issueIds: JSON.parse(row.issueIds) as IssueId[],
  };
}
