s += '''
/**
 * Maps each address (lower-cased) to the user id of its active member in this
 * workspace. Addresses that belong to no active member are absent from the map.
 */
export async function findActiveMemberUserIdsByEmail(
  orgId: OrgId,
  emails: readonly string[],
): Promise<ReadonlyMap<string, UserId>> {
  const found = new Map<string, UserId>();
  if (emails.length === 0) return found;

  const lowered = emails.map((email) => email.toLowerCase());
  const rows = getDb()
    .select({ email: sql<string>`lower(${users.email})`, userId: members.userId })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
        inArray(sql`lower(${users.email})`, lowered),
      ),
    )
    .all();

  for (const row of rows) {
    if (!found.has(row.email)) found.set(row.email, row.userId as UserId);
  }
  return found;
}
'''
s = s.replace('import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";', 'import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";', 1)
open(p, 'w').write(s)
print("ok")
