  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {''', '''/** Rate-limit bucket shared with single issue creation: one unit per row. */
const ISSUE_CREATE_BUCKET = "issue:create";

/**
 * Bulk import of a whole upload. Gates run in the same order as `createIssue`
 * (scope, project, archive, permission), then the upload key is checked for a
 * replay, then the plan quota and the rate allowance are checked for the whole
 * batch. Only when every gate passes is anything written — in one transaction —
 * and a single `issues.imported` event is published for the batch.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const replay = await replayIssueImport(input.orgId, input.importKey);
  if (replay) return replay;

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assigneeByEmail = await memberRepo.findActiveMemberUserIdsByEmail(
    input.orgId,
    input.rows.flatMap((row) =>
      row.assigneeEmail === null ? [] : [row.assigneeEmail],
    ),
  );

  const created = await issueRepo.insertIssueImport({
    orgId: input.orgId,
    projectId: project.id,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      dueAt: row.dueAt,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assigneeByEmail.get(row.assigneeEmail.toLowerCase()) ?? null),
      labelNames: row.labels,
    })),
  });

  if (created === null) {
    // A concurrent import with this key committed first; answer with its result.
    return requireFound(
      await replayIssueImport(input.orgId, input.importKey),
      "IssueImport",
      input.importKey,
    );
  }

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: project.id,
    importKey: input.importKey,
    issueIds: created.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: project.id,
    issues: created,
    replayed: false,
  };
}

/** The first import's result for this key in this workspace, or `null` if none. */
async function replayIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportResult | null> {
  const stored = await issueRepo.findIssueImport(orgId, importKey);
  if (!stored) return null;

  const issues = await Promise.all(
    stored.issueIds.map(async (issueId) =>
      requireFound(
        await issueRepo.findIssueById(orgId, issueId),
        "Issue",
        issueId,
      ),
    ),
  );

  return {
    importKey,
    projectId: stored.projectId,
    issues,
    replayed: true,
  };
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {''')

